import fs from "node:fs";
import { gunzipSync } from "node:zlib";

const MANIFEST_B64 = "";
const WINNER_SOURCE_IDS_B64 = "";
const manifest = JSON.parse(gunzipSync(Buffer.from(MANIFEST_B64, "base64")).toString("utf8"));
const winnerSourceIds = JSON.parse(gunzipSync(Buffer.from(WINNER_SOURCE_IDS_B64, "base64")).toString("utf8"));
const moduleSource = `
import { gunzipSync } from "node:zlib";
import { pool } from "./db.js";

const REPAIR_SLUG = "dedupe-song-catalog-and-footer-v1";
const FOOTER = "::::::::::::::::::::::::::::::::\\nwww.GuitarraIA.com";
const manifest = JSON.parse(gunzipSync(Buffer.from("${MANIFEST_B64}", "base64")).toString("utf8"));

function useful(value) {
  return value !== null && value !== undefined && value !== "" &&
    !(Array.isArray(value) && value.length === 0);
}

function withFooter(value) {
  const text = String(value || "").trimEnd();
  if (!text) return value;
  if (text.endsWith(FOOTER)) return text + "\\n";
  return text + "\\n\\n" + FOOTER + "\\n";
}

function mediaScore(data, prefix) {
  let score = 0;
  for (const [key, value] of Object.entries(data || {})) {
    if (key.startsWith(prefix) && useful(value)) score += 1;
  }
  if (prefix === "spotify_" && data?.spotify_match_status === "matched") score += 20;
  if (prefix === "youtube_" && data?.youtube_analysis_status === "ready") score += 20;
  return score;
}

function mergeWinner(winner, others) {
  const candidates = [winner, ...others];
  const merged = { ...winner };

  // Preserve useful metadata from any duplicate even when its musical content
  // is less complete than the selected winner.
  for (const candidate of candidates) {
    for (const [key, value] of Object.entries(candidate || {})) {
      if (!useful(merged[key]) && useful(value)) merged[key] = value;
    }
  }

  for (const key of [
    "is_easy_pick", "is_unplugged", "is_hero", "is_trending",
    "youtube_practice_enabled"
  ]) {
    merged[key] = candidates.some((item) => Boolean(item?.[key]));
  }
  merged.views = Math.max(...candidates.map((item) => Number(item?.views || 0)));

  for (const prefix of ["spotify_", "youtube_"]) {
    const best = [...candidates].sort((a, b) => mediaScore(b, prefix) - mediaScore(a, prefix))[0];
    if (best) {
      for (const [key, value] of Object.entries(best)) {
        if (key.startsWith(prefix) && useful(value)) merged[key] = value;
      }
    }
  }

  // The audit selected this record specifically for its lyrics/chords.
  for (const key of ["id", "title", "artist_name", "artist_id", "slug", "artist_slug"]) {
    if (useful(winner[key])) merged[key] = winner[key];
  }
  merged.content_raw = withFooter(winner.content_raw);
  merged.tablature = withFooter(winner.tablature);
  merged.has_chords = Boolean(merged.has_chords || String(merged.content_raw || "").trim());
  merged.has_tablature = Boolean(merged.has_tablature || String(merged.tablature || "").trim());
  merged.catalog_deduplicated_by = REPAIR_SLUG;
  merged.catalog_deduplicated_at = new Date().toISOString();
  return merged;
}

async function redirectReferences(client, oldId, winnerId) {
  await client.query(
    "UPDATE entity_records " +
      "SET data=jsonb_set(data,'{song_id}',to_jsonb($2::text),true),updated_date=NOW() " +
      "WHERE entity_name<>'Song' AND data->>'song_id'=$1",
    [oldId, winnerId]
  );
  await client.query(
    "UPDATE entity_records SET data=jsonb_set(" +
      "data,'{song_ids}'," +
      "(SELECT jsonb_agg(CASE WHEN value #>> '{}'=$1 THEN to_jsonb($2::text) ELSE value END) " +
      "FROM jsonb_array_elements(data->'song_ids') AS elements(value)),true" +
      "),updated_date=NOW() WHERE entity_name<>'Song' " +
      "AND jsonb_typeof(data->'song_ids')='array' AND data->'song_ids' ? $1",
    [oldId, winnerId]
  );
}

export async function dedupeSongCatalogAndAddFooter() {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("SELECT pg_advisory_xact_lock(hashtext($1))", [REPAIR_SLUG]);
    const prior = await client.query(
      "SELECT id FROM entity_records WHERE entity_name='MigrationRepair' AND data->>'slug'=$1 AND data->>'status'='completed' LIMIT 1",
      [REPAIR_SLUG]
    );
    if (prior.rows[0]) {
      await client.query("COMMIT");
      console.log("Song catalog dedupe already completed");
      return { status: "already_completed" };
    }

    const rows = await client.query(
      "SELECT id,data FROM entity_records WHERE entity_name='Song' FOR UPDATE"
    );
    const byId = new Map(rows.rows.map((row) => [String(row.id), row]));
    const deletedIds = [];
    const deletedSourceIds = [];
    let mergedGroups = 0;

    for (const group of manifest) {
      const winnerRow = byId.get(group.winner_id);
      if (!winnerRow) throw new Error("Missing dedupe winner " + group.winner_id);
      const duplicateRows = group.delete_ids.map((id) => byId.get(id)).filter(Boolean);
      const merged = mergeWinner(
        { ...winnerRow.data, id: String(winnerRow.id) },
        duplicateRows.map((row) => ({ ...row.data, id: String(row.id) }))
      );
      delete merged.id;
      await client.query(
        "UPDATE entity_records SET data=$2::jsonb,updated_date=NOW() WHERE id=$1 AND entity_name='Song'",
        [winnerRow.id, JSON.stringify(merged)]
      );

      for (const row of duplicateRows) {
        const oldId = String(row.id);
        await redirectReferences(client, oldId, String(winnerRow.id));
        deletedIds.push(oldId);
        if (row.data?.source_id) deletedSourceIds.push(String(row.data.source_id));
      }
      if (duplicateRows.length) {
        await client.query(
          "DELETE FROM entity_records WHERE entity_name='Song' AND id::text=ANY($1::text[])",
          [duplicateRows.map((row) => String(row.id))]
        );
      }
      mergedGroups += 1;
    }

    // Add the requested signature to both supported musical-content fields
    // for every surviving song, including songs that were never duplicated.
    const survivors = await client.query(
      "SELECT id,data FROM entity_records WHERE entity_name='Song' FOR UPDATE"
    );
    let footeredSongs = 0;
    for (const row of survivors.rows) {
      const contentRaw = withFooter(row.data?.content_raw);
      const tablature = withFooter(row.data?.tablature);
      if (contentRaw !== row.data?.content_raw || tablature !== row.data?.tablature) {
        const patched = { ...row.data, content_raw: contentRaw, tablature };
        await client.query(
          "UPDATE entity_records SET data=$2::jsonb,updated_date=NOW() WHERE id=$1",
          [row.id, JSON.stringify(patched)]
        );
        footeredSongs += 1;
      }
    }

    const audit = {
      slug: REPAIR_SLUG,
      status: "completed",
      groups_merged: mergedGroups,
      songs_deleted: deletedIds.length,
      songs_remaining: survivors.rows.length,
      songs_footer_updated: footeredSongs,
      deleted_song_ids: deletedIds,
      deleted_source_ids: [...new Set(deletedSourceIds)],
      completed_at: new Date().toISOString(),
    };
    await client.query(
      "INSERT INTO entity_records(entity_name,data) VALUES('MigrationRepair',$1::jsonb)",
      [JSON.stringify(audit)]
    );
    await client.query("COMMIT");
    console.log("Song catalog dedupe completed", {
      groups: audit.groups_merged,
      deleted: audit.songs_deleted,
      remaining: audit.songs_remaining,
      footered: audit.songs_footer_updated,
    });
    return audit;
  } catch (error) {
    await client.query("ROLLBACK");
    console.error("Song catalog dedupe rolled back", error);
    throw error;
  } finally {
    client.release();
  }
}
`;

fs.mkdirSync("server", { recursive: true });
fs.writeFileSync("server/dedupe-song-catalog.js", moduleSource.trimStart(), "utf8");

const indexPath = "server/index.js";
let index = fs.readFileSync(indexPath, "utf8");
if (!index.includes('from "./dedupe-song-catalog.js"')) {
  index = index.replace(
    'import express from "express";',
    'import express from "express";\nimport { dedupeSongCatalogAndAddFooter } from "./dedupe-song-catalog.js";'
  );
}
if (!index.includes("await dedupeSongCatalogAndAddFooter();")) {
  const anchor = "await repairInvertedLote001Followup2();";
  if (!index.includes(anchor)) throw new Error("Lote 001 follow-up 2 anchor is missing");
  index = index.replace(anchor, anchor + "\nawait dedupeSongCatalogAndAddFooter();");
}
fs.writeFileSync(indexPath, index, "utf8");

const deletedSourceIds = [...new Set(manifest.flatMap((group) => group.delete_source_ids || []))];
const migrationPath = "server/base44-migration.js";
let migration = fs.readFileSync(migrationPath, "utf8");
if (!migration.includes("DEDUPE_EXCLUDED_SONG_SOURCE_IDS")) {
  migration = migration.replace(
    'const ALLOWED_ENTITIES = ["Artist", "Song", "BlogPost", "Infographic", "AmazonProduct"];',
    'const ALLOWED_ENTITIES = ["Artist", "Song", "BlogPost", "Infographic", "AmazonProduct"];\n' +
      'const DEDUPE_CONTENT_FOOTER = "::::::::::::::::::::::::::::::::\\nwww.GuitarraIA.com";\n' +
      'const DEDUPE_EXCLUDED_SONG_SOURCE_IDS = new Set(' + JSON.stringify(deletedSourceIds) + ');\n' +
      'const DEDUPE_PRESERVED_SONG_SOURCE_IDS = new Set(' + JSON.stringify(winnerSourceIds) + ');\n' +
      'function dedupeFooter(value) { const text=String(value || "").trimEnd(); if (!text) return value; return text.endsWith(DEDUPE_CONTENT_FOOTER) ? text + "\\n" : text + "\\n\\n" + DEDUPE_CONTENT_FOOTER + "\\n"; }'
  );
  migration = migration.replace(
    "const record = cleanRecord(original);",
    'const record = cleanRecord(original);\n' +
      '    if (entity === "Song" && DEDUPE_EXCLUDED_SONG_SOURCE_IDS.has(record.sourceId)) continue;\n' +
      '    if (entity === "Song") { record.data.content_raw=dedupeFooter(record.data.content_raw); record.data.tablature=dedupeFooter(record.data.tablature); }'
  );
  migration = migration.replace(
    'if (existing.rows[0]) {',
    'if (existing.rows[0]) {\n      if (entity === "Song" && DEDUPE_PRESERVED_SONG_SOURCE_IDS.has(record.sourceId)) { updated += 1; continue; }'
  );
}
fs.writeFileSync(migrationPath, migration, "utf8");
console.log("Song catalog dedupe and footer repair installed.");
